if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$type=$_POST['type']??'mcq';if(!in_array($type,['mcq','essay','matrix_disc'],true))$type='mcq';$text=trim((string)($_POST['question_text']??''));if($text==='')exit('Pertanyaan wajib diisi.');$useKey=$type==='matrix_disc'?0:(isset($_POST['use_answer_key'])?1:0);$opts=[];foreach($letters as $k)$opts[$k]=trim((string)($_POST[$k]??''));if($type==='mcq'){$opts=array_filter($opts,fn($v)=>$v!=='');if(count($opts)<2)exit('Pilihan ganda minimal 2 pilihan.');}$correct=$useKey?strtoupper(trim((string)($_POST['correct_option']??''))):null;if($type==='mcq'&&$useKey&&!isset($opts[$correct]))exit('Kunci jawaban harus termasuk pilihan aktif.');if($type!=='mcq')$correct=null;$points=$useKey?max(0,(float)($_POST['points']??1)):0;$essayKey=$useKey&&$type==='essay'?trim((string)($_POST['essay_answer_key']??'')):null;$matrixMirip=$matrixTidak=null;if($type==='matrix_disc'){$matrixMirip=strtoupper(trim((string)($_POST['matrix_correct_mirip']??'A')));$matrixTidak=strtoupper(trim((string)($_POST['matrix_correct_tidak']??'A')));if(!in_array($matrixMirip,['A','B','C','D'],true)||!in_array($matrixTidak,['A','B','C','D'],true))exit('Kunci matriks harus A-D.');}
$imagePath=$q['question_image']??null;if(($_POST['remove_image']??'')==='1'){if($imagePath&&is_file(__DIR__.'/../'.$imagePath))@unlink(__DIR__.'/../'.$imagePath);$imagePath=null;}if(!empty($_FILES['question_image']['tmp_name'])){$f=$_FILES['question_image'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']!==UPLOAD_ERR_OK||!isset($allowed[$mime])||$f['size']>5*1024*1024)exit('Gambar tidak valid atau terlalu besar.');$dir=__DIR__.'/../uploads/questions';if(!is_dir($dir))mkdir($dir,0755,true);$name='q_'.bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))exit('Gagal menyimpan gambar.');if($imagePath&&is_file(__DIR__.'/../'.$imagePath))@unlink(__DIR__.'/../'.$imagePath);$imagePath='uploads/questions/'.$name;}
$sql='UPDATE questions SET type=?,question_text=?,question_image=?,essay_answer_key=?,option_a=?,option_b=?,option_c=?,option_d=?,option_e=?,option_f=?,option_g=?,option_h=?,use_answer_key=?,correct_option=?,matrix_correct_mirip=?,matrix_correct_tidak=?,points=? WHERE id=?';db()->prepare($sql)->execute([$type,$text,$imagePath,$essayKey,$opts['A']??null,$opts['B']??null,$opts['C']??null,$opts['D']??null,$opts['E']??null,$opts['F']??null,$opts['G']??null,$opts['H']??null,$useKey,$correct,$matrixMirip,$matrixTidak,$points,$id]);header('Location: questions.php?id='.$examId.'&updated=1');exit;}
