<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Soal</title><link rel="stylesheet" href="assets/admin-ui.css"></head><body><div class="admin-layout"><main class="admin-main"><header class="admin-topbar"><div class="top-left"><h1>Edit Soal</h1></div></header><div class="admin-content"><div class="page-head"><div><div class="backline"><a href="questions.php?id=<?=$examId?>">← Kembali ke Kelola Soal</a></div><h2 class="page-title">Edit Soal</h2><p class="page-subtitle">Jumlah pilihan dapat ditambah atau dikurangi.</p></div></div><section class="ui-card edit-question-card"><form method="post" enctype="multipart/form-data" class="exam-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><div class="form-grid"><div><label>Jenis</label><select name="type" id="editType"><option value="mcq" <?=$q['type']==='mcq'?'selected':''?>>Pilihan Ganda</option><option value="essay" <?=$q['type']==='essay'?'selected':''?>>Essay</option><option value="matrix_disc" <?=$q['type']==='matrix_disc'?'selected':''?>>Matriks / DISC</option></select></div></div><label>Pertanyaan</label><textarea name="question_text" required><?=htmlspecialchars($q['question_text'])?></textarea><label>Gambar soal</label><?php if(!empty($q['question_image'])):?><img class="question-image edit-preview" src="<?=htmlspecialchars(app_url($q['question_image']))?>"><label class="check-row"><input type="checkbox" name="remove_image" value="1"> Hapus gambar</label><?php endif;?><input type="file" name="question_image" accept="image/jpeg,image/png,image/webp,image/gif"><div id="editMcq"><div id="optionList" class="form-grid compact-grid"></div><div style="display:flex;gap:8px;margin:10px 0"><button type="button" class="ui-btn secondary" id="addOption">+ Tambah Pilihan</button><button type="button" class="ui-btn secondary" id="removeOption">− Kurangi Pilihan</button></div></div><div id="gradingFields"><label class="check-row"><input type="checkbox" name="use_answer_key" id="useKey" <?=!empty($q['use_answer_key'])?'checked':''?>> Gunakan Kunci Jawaban &amp; Poin</label><div id="gradingDetails"><label>Kunci jawaban</label><select name="correct_option" id="correctOption"></select><label>Poin</label><input type="number" name="points" min="0" step="0.5" value="<?=htmlspecialchars((string)$q['points'])?>"></div></div><div id="editEssay"><label>Jawaban acuan</label><textarea name="essay_answer_key"><?=htmlspecialchars((string)($q['essay_answer_key']??''))?></textarea></div><div id="editMatrix"><p class="ui-sub">Matriks / DISC tidak menggunakan kunci jawaban atau poin.</p><div class="form-grid"><div><label>Kunci MIRIP</label><select name="matrix_correct_mirip"><?php foreach(['A','B','C','D'] as $k):?><option <?=$q['matrix_correct_mirip']===$k?'selected':''?>><?=$k?></option><?php endforeach;?></select></div><div><label>Kunci TIDAK MIRIP</label><select name="matrix_correct_tidak"><?php foreach(['A','B','C','D'] as $k):?><option <?=$q['matrix_correct_tidak']===$k?'selected':''?>><?=$k?></option><?php endforeach;?></select></div></div></div><div class="form-actions"><a class="ui-btn secondary" href="questions.php?id=<?=$examId?>">Batal</a><button class="ui-btn">Simpan Perubahan</button></div></form></section></div></main></div><script>const saved=<?=json_encode(array_map(fn($k)=>(string)($q['option_'.strtolower($k)]??''),$letters))?>,letters='ABCDEFGH',type=document.getElementById('editType'),list=document.getElementById('optionList'),correct=document.getElementById('correctOption'),useKey=document.getElementById('useKey');let count=<?=$active?>;function render(){let old={};list.querySelectorAll('input').forEach(x=>old[x.name]=x.value);let selected=correct.value||<?=json_encode($q['correct_option']??'A')?>;list.innerHTML='';correct.innerHTML='';for(let i=0;i<count;i++){let k=letters[i],v=old[k]??saved[i]??'';list.insertAdjacentHTML('beforeend',`<div><label>Pilihan ${k}</label><input name="${k}" value="${String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;')}" ${i<2?'required':''}></div>`);correct.insertAdjacentHTML('beforeend',`<option value="${k}">${k}</option>`)}correct.value=[...correct.options].some(o=>o.value===selected)?selected:'A';addOption.disabled=count>=8;removeOption.disabled=count<=2}function sync(){let m=type.value==='matrix_disc',e=type.value==='essay';editMcq.style.display=(type.value==='mcq'||m)?'block':'none';editEssay.style.display=e?'block':'none';editMatrix.style.display=m?'block':'none';gradingFields.style.display=m?'none':'block';gradingDetails.style.display=useKey.checked&&type.value==='mcq'?'block':'none';if(m)useKey.checked=false}addOption.onclick=()=>{if(count<8){count++;render()}};removeOption.onclick=()=>{if(count>2){count--;render()}};type.onchange=sync;useKey.onchange=sync;render();sync();</script></body></html>